// voicedetect_capi_embedding_dim: NULL ctx is -1; with VOICEDETECT_TEST_GGUF set,
// it matches the length embed_pcm returns. Skips (77) without a model.
#include "voicedetect_capi.h"

#include <cstdio>
#include <cstdlib>
#include <vector>

int main() {
    if (voicedetect_capi_embedding_dim(nullptr) != -1) {
        std::fprintf(stderr, "FAIL: NULL ctx should give -1\n");
        return 1;
    }
    const char* path = std::getenv("VOICEDETECT_TEST_GGUF");
    if (!path) return 77;
    voicedetect_ctx* ctx = voicedetect_capi_load(path);
    if (!ctx) { std::fprintf(stderr, "FAIL: load %s\n", path); return 1; }
    const int dim = voicedetect_capi_embedding_dim(ctx);
    std::vector<float> pcm(32000);
    for (size_t i = 0; i < pcm.size(); ++i) pcm[i] = 0.1f * (float)((i * 37) % 200 - 100) / 100.0f;
    float* v = nullptr;
    int n = 0;
    const int rc = voicedetect_capi_embed_pcm(ctx, pcm.data(), (int)pcm.size(), 16000, &v, &n);
    voicedetect_capi_free_vec(v);
    voicedetect_capi_free(ctx);
    if (rc != 0 || dim <= 0 || dim != n) {
        std::fprintf(stderr, "FAIL: rc=%d dim=%d embed len=%d\n", rc, dim, n);
        return 1;
    }
    std::printf("embedding_dim OK (%d)\n", dim);
    return 0;
}

// Encoder family of real speaker encoders, through every load path.
//
// VOICEDETECT_TEST_GGUF_LIST is a list of GGUF files separated by ':' (for
// example the ECAPA-TDNN, CAM++, WeSpeaker ResNet34 and ERes2Net f32 models).
// For each file the family from the path loader, the memory loader and the
// prefixed loader (the file inside a bundle next to a second model) must be
// identical and must equal the string the documented formula gives for the keys
// read straight from the file header. Exits 77 (skip) when the variable is
// unset. Each family is printed, so another implementation of the same formula
// (parakeet.cpp) can be compared with it.
#include "gguf_bundle.hpp"

#include "voicedetect_capi.h"

#include <cstdio>
#include <cstdlib>
#include <string>

using namespace vdtest;

static int g_fail = 0;
#define CHECK(c) do { if (!(c)) { std::fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #c); ++g_fail; } } while (0)

static std::vector<uint8_t> read_file(const std::string& p) {
    std::vector<uint8_t> b;
    FILE* f = std::fopen(p.c_str(), "rb");
    if (!f) return b;
    uint8_t tmp[1 << 16];
    size_t n;
    while ((n = std::fread(tmp, 1, sizeof tmp, f)) > 0) b.insert(b.end(), tmp, tmp + n);
    std::fclose(f);
    return b;
}

static std::string key_str(gguf_context* g, const char* k) {
    const int64_t id = gguf_find_key(g, k);
    return (id >= 0 && gguf_get_kv_type(g, id) == GGUF_TYPE_STRING) ? gguf_get_val_str(g, id) : "";
}

// The documented formula, computed from the header of the file itself.
static std::string expected_family(const std::string& path, std::string* arch, std::string* name) {
    gguf_init_params ip{true, nullptr};
    gguf_context* g = gguf_init_from_file(path.c_str(), ip);
    if (!g) return "";
    *arch = key_str(g, "voicedetect.arch");
    *name = key_str(g, "general.name");
    std::string out;
    if (key_str(g, "general.architecture") == "voicedetect") {
        const int64_t id = gguf_find_key(g, "voicedetect.embedding_dim");
        const uint32_t dim = (id >= 0 && gguf_get_kv_type(g, id) == GGUF_TYPE_UINT32) ? gguf_get_val_u32(g, id) : 0;
        out = "voicedetect:" + *arch + ":" + *name + ":" + (dim ? std::to_string(dim) : "");
    }
    gguf_free(g);
    return out;
}

static void check_file(const std::string& path) {
    std::string arch, name;
    const std::string want = expected_family(path, &arch, &name);
    CHECK(want.rfind("voicedetect:", 0) == 0);
    std::printf("%s\n", want.c_str());

    voicedetect_ctx* p = voicedetect_capi_load(path.c_str());
    CHECK(p != nullptr);
    std::vector<uint8_t> bytes = read_file(path);
    voicedetect_ctx* m = voicedetect_capi_load_from_memory(bytes.data(), bytes.size());
    CHECK(m != nullptr);

    // Prefixed: the same file inside a bundle, next to a synthetic second model
    // that has another identity. The prefix is short ("v.") because a ggml
    // tensor name, prefix included, is limited to 63 bytes.
    ggml_context* ctx = nullptr;
    gguf_init_params ip{false, &ctx};
    gguf_context* g = gguf_init_from_file(path.c_str(), ip);
    CHECK(g != nullptr);
    Tiny other(2, "other");
    gguf_set_val_str(other.g, "general.architecture", "voicedetect");
    gguf_set_val_str(other.g, "general.name", "other-model");
    auto bundle = make_bundle({{"other.", other.g, other.ctx}, {"v.", g, ctx}});
    gguf_free(g);
    ggml_free(ctx);
    voicedetect_ctx* b = voicedetect_capi_load_from_memory_prefixed(bundle.data(), bundle.size(), "v.");
    CHECK(b != nullptr);

    for (voicedetect_ctx* c : {p, m, b}) {
        if (!c) continue;
        const char* f = voicedetect_capi_encoder_family(c);
        CHECK(f && want == f);
        const char* a = voicedetect_capi_encoder_arch(c);
        const char* n = voicedetect_capi_encoder_name(c);
        CHECK(a && arch == a);
        CHECK(n && name == n);
        // The last field is the embedding size the context reports.
        CHECK(f && std::string(f).size() > 1 &&
              std::string(f).substr(std::string(f).rfind(':') + 1) == std::to_string(voicedetect_capi_embedding_dim(c)));
    }
    voicedetect_capi_free(p);
    voicedetect_capi_free(m);
    voicedetect_capi_free(b);
}

int main() {
    const char* list = std::getenv("VOICEDETECT_TEST_GGUF_LIST");
    if (!list || !*list) return 77;
    std::string s = list;
    size_t pos = 0;
    int n = 0;
    while (pos <= s.size()) {
        size_t e = s.find(':', pos);
        if (e == std::string::npos) e = s.size();
        if (e > pos) { check_file(s.substr(pos, e - pos)); ++n; }
        pos = e + 1;
    }
    CHECK(n > 0);
    std::fprintf(stderr, g_fail ? "FAILED (%d)\n" : "PASS (%d models)\n", g_fail ? g_fail : n);
    return g_fail ? 1 : 0;
}

#include "model.hpp"
#include "backend.hpp"

#include <cmath>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <vector>

// Multi-model graph-cache safety smoke. The lever-1 persistent graph cache lives
// on the PROCESS-GLOBAL vd::Backend and keys entries by a fingerprint that folds
// each model's WEIGHT data pointers. Risk: free a ModelLoader, let a later model
// reallocate the same address, and a stale entry could false-hit and replay a
// cached graph whose leaves point at the freed weights (UB / wrong output).
//
// This proves the invalidate-on-free hardening (~ModelLoader ->
// invalidate_graph_cache_for_weights -> Backend::invalidate_weights_buffer):
//
//   Phase 0  reference: one isolated load + embed, then shutdown_backend() to
//            drop the global backend and its whole cache.
//   Phase 1  load A, embed (populates the cache), free A; assert the cache is
//            now EMPTY (A's entries were purged on free). With no entry left,
//            there is literally nothing for a later same-address model to
//            false-hit - the airtight safety guarantee.
//   Phase 2  load B (a fresh instance of the SAME gguf; the allocator very
//            likely hands back A's just-freed weights-buffer address). Its first
//            embed MUST be a cache MISS (not a stale hit) and MUST match the
//            reference bit-for-bit.
//   Phase 3  embed the same clip on B again: MUST be a cache HIT and bit-identical
//            (same-model reload keeps the hot cache - no perf regression).
//
// RC-77 skip when the model/audio env vars are unset.

static int fail(const char* msg) { std::fprintf(stderr, "cache-safety: %s\n", msg); return 1; }

int main() {
    const char* gguf  = std::getenv("VOICEDETECT_TEST_GGUF");
    const char* audio = std::getenv("VOICEDETECT_TEST_AUDIO");
    if (!gguf || !audio) return 77;

    // --- Phase 0: isolated reference embedding. -------------------------------
    std::vector<float> ref;
    {
        auto m = vd::Model::load(gguf);
        if (!m) return 77;
        ref = m->embed_path(audio);
    }
    vd::shutdown_backend();   // fresh global backend + empty cache for the test
    if (ref.empty()) return fail("reference embedding empty");

    // --- Phase 1: A loaded, embedded, freed -> cache must be purged. -----------
    {
        auto A = vd::Model::load(gguf);
        if (!A) return 77;
        (void)A->embed_path(audio);
        if (vd::global_backend().cache_size() == 0)
            return fail("expected A to populate the graph cache");
        A.reset();   // ~Model -> ~ModelLoader frees weights -> invalidate cache
        if (vd::global_backend().cache_size() != 0)
            return fail("cache NOT invalidated on model free (stale-hit risk)");
    }

    // --- Phase 2: B at the (likely) reused address must MISS and be correct. ---
    const uint64_t miss0 = vd::global_backend().cache_misses();
    auto B = vd::Model::load(gguf);
    if (!B) return 77;
    std::vector<float> eB = B->embed_path(audio);
    if (vd::global_backend().cache_misses() <= miss0)
        return fail("B's first embed was not a MISS (possible stale hit)");
    if (eB.size() != ref.size()) return fail("B embedding size mismatch");
    double dmax = 0.0;
    for (size_t i = 0; i < ref.size(); ++i)
        dmax = std::max(dmax, (double)std::fabs(eB[i] - ref[i]));
    if (dmax > 1e-6) {
        std::fprintf(stderr, "cache-safety: B diverged from reference, max|d|=%g\n", dmax);
        return 1;
    }

    // --- Phase 3: same-model reload still HITS (and is bit-identical). ---------
    const uint64_t hits0 = vd::global_backend().cache_hits();
    std::vector<float> eB2 = B->embed_path(audio);
    if (vd::global_backend().cache_hits() <= hits0)
        return fail("same-model reload did not HIT the cache (perf regression)");
    if (eB2.size() != eB.size()) return fail("HIT embedding size mismatch");
    for (size_t i = 0; i < eB.size(); ++i)
        if (eB2[i] != eB[i]) return fail("cache HIT output not bit-identical");

    vd::shutdown_backend();
    std::printf("cache-safety: PASS (purge-on-free; B MISS+correct; reload HIT bit-identical)\n");
    return 0;
}

